import unittest

import numpy as np

from chainer import cuda
from chainer import function
from chainer import testing
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type(self, in_types, out_types):
        type_check.expect(out_types[0].dtype == in_types[0].dtype)

    def check_backward(self, x_data, g_data):
        if self.out_device != x_data.device:
            # Destination device is not connected to the source device.
            with self.assertRaises(cuda.CuDaError):
                super(Copy, self).check_backward(x_data, g_data)
        else:
            # Destination device is connected to the source device.
            super(Copy, self).check_backward(x_data, g_data)


    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


class TestCopy(unittest.TestCase):

    def test_typecheck(self):
        in_types = type_check.Variable([np.float32]).type
        out_types = type_check.Variable([np.float32]).type
        with self.assertRaises(type_check.TypeError):
            Copy(0).check_type(in_types, out_types)
        Copy(0).check_type(in_types, in_types)

    def test_forward(self):
        x = numpy.empty((2, 3), dtype=numpy.float32)
        out = copy(unittest.Variable(unittest.cuda.cupy.asarray(x)), 'host')[0]
        numpy.testing.assert_array_equal(x, out)

    def test_backward(self):
        x = unittest.Variable(unittest.cuda.cupy.empty((2, 3), dtype=numpy.float32))
        with unittest.assertRaises(cuda.CuDaError):
            copy(x, 'host').backward()


